"use client";

import { useEffect, useRef, useState } from "react";
import gsap from "gsap";
import { ImmersiveFullscreenNavContent } from "./immersive-fullscreen-nav-content";

const CLIPS = {
  bottom: {
    closedInitial: "polygon(0% 100%, 100% 100%, 100% 100%, 0% 100%)",
    open: "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)",
    closedFinal: "polygon(0% 0%, 100% 0%, 100% 0%, 0% 0%)",
  },
  top: {
    closedInitial: "polygon(0% 0%, 100% 0%, 100% 0%, 0% 0%)",
    open: "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)",
    closedFinal: "polygon(0% 100%, 100% 100%, 100% 100%, 0% 100%)",
  },
  left: {
    closedInitial: "polygon(0% 0%, 0% 0%, 0% 100%, 0% 100%)",
    open: "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)",
    closedFinal: "polygon(100% 0%, 100% 0%, 100% 100%, 100% 100%)",
  },
  right: {
    closedInitial: "polygon(100% 0%, 100% 0%, 100% 100%, 100% 100%)",
    open: "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)",
    closedFinal: "polygon(0% 0%, 0% 0%, 0% 100%, 0% 100%)",
  },
};

export function FullScreenNavigation({
  links = [],
  brand = "Hyperiux",
  brandHref = "/",
  clipOrigin = "bottom",
  overlayBg = "#000000",
  linkColor = "#ffffff",
  linkHoverColor = "#a3a3a3",
  linkSizeClass = "text-5xl",
  headerClassName = "",
  openDuration = 1.2,
  closeDuration = 1.2,
  headerOpenColor = "#ffffff",
  children,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const overlayRef = useRef(null);
  const linksWrapperRef = useRef(null);
  const tlRef = useRef(null);
  const isAnimatingRef = useRef(false);

  const { closedInitial, open, closedFinal } = CLIPS[clipOrigin] ?? CLIPS.bottom;

  useEffect(() => {
    document.body.style.overflow = isOpen ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  const openMenu = () => {
    setIsOpen(true);
    tlRef.current?.kill();
    gsap.set(overlayRef.current, { clipPath: closedInitial });
    gsap.set(linksWrapperRef.current, { opacity: 1, scale: 1 });
    tlRef.current = gsap.timeline({
      onStart: () => {
        isAnimatingRef.current = true;
      },
      onComplete: () => {
        isAnimatingRef.current = false;
      },
    });
    tlRef.current.to(overlayRef.current, {
      clipPath: open,
      duration: openDuration,
      delay: 0.2,
      ease: "power4.inOut",
    });
  };

  const closeMenu = () => {
    tlRef.current?.kill();
    tlRef.current = gsap.timeline({
      onStart: () => {
        isAnimatingRef.current = true;
      },
      onComplete: () => {
        isAnimatingRef.current = false;
        setIsOpen(false);
      },
    });
    tlRef.current
      .to(linksWrapperRef.current, { scale: 0.9, opacity: 0.5, duration: 0.7, ease: "power2.in" })
      .to(
        overlayRef.current,
        {
          clipPath: closedFinal,
          duration: closeDuration,
          ease: "power4.inOut",
        },
        "<"
      );
  };

  const toggleMenu = () => {
    if (isAnimatingRef.current) return;
    if (isOpen) closeMenu();
    else openMenu();
  };

  return (
    <>
      <header className={`fixed top-0 left-0 right-0 z-70 flex h-16 items-center justify-between px-8 ${headerClassName}`}>
        <a
          href={brandHref}
          style={{ color: isOpen ? headerOpenColor : undefined }}
          className={`text-lg tracking-tight transition-colors duration-500 ${isOpen ? "delay-500" : "text-black delay-500"}`}
        >
          {brand}
        </a>

        <button
          onClick={toggleMenu}
          aria-label="Toggle menu"
          aria-expanded={isOpen}
          className="flex h-10 w-10 cursor-pointer flex-col items-center justify-center gap-1.5"
        >
          {[0, 1, 2].map((bar) => (
            <span
              key={bar}
              style={{ backgroundColor: isOpen ? headerOpenColor : undefined }}
              className={`block h-px w-6 transition-all duration-700 ease-in-out ${
                bar === 0 ? (isOpen ? "translate-y-1.25 rotate-45" : "bg-black") : ""
              } ${bar === 1 ? (isOpen ? "opacity-0 scale-x-0" : "bg-black duration-500") : ""} ${
                bar === 2 ? (isOpen ? "-translate-y-1.25 -rotate-45" : "bg-black") : ""
              }`}
            />
          ))}
        </button>
      </header>

      <nav
        ref={overlayRef}
        style={{ clipPath: closedInitial, backgroundColor: overlayBg }}
        className={`fixed inset-0 z-60 flex flex-col items-center justify-center gap-2 ${isOpen ? "pointer-events-auto" : "pointer-events-none"}`}
        aria-hidden={!isOpen}
      >
        <div ref={linksWrapperRef} className="flex h-screen w-screen flex-col items-center justify-center">
          {children
            ? children(isOpen, closeMenu)
            : links.map(({ label, href }) => (
                <a
                  key={label}
                  href={href}
                  onClick={closeMenu}
                  style={{ color: linkColor }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.color = linkHoverColor;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.color = linkColor;
                  }}
                  className={`${linkSizeClass} font-normal tracking-tight transition-colors`}
                >
                  {label}
                </a>
              ))}
        </div>
      </nav>
    </>
  );
}

const NAV_CONFIG = {
  brand: "Hyperiux",
  brandHref: "/",
  clipOrigin: "bottom",
  overlayBg: "#1a1a2e",
  headerOpenColor: "#ff6600",
  openDuration: 1.2,
  closeDuration: 1.2,
};

const NAV_CONTENT = {
  agencyName: "",
  tagline: "Crafting digital experiences.",
  location: "Noida, India",
  links: [
    { label: "Home", href: "/" },
    { label: "Work", href: "/work" },
    { label: "About", href: "/about" },
    { label: "Contact", href: "/contact" },
  ],
  images: ["/assets/img/image01.webp", "/assets/img/image02.webp"],
  socials: [
    { type: "instagram", href: "#" },
    { type: "facebook", href: "#" },
    { type: "twitter", href: "#" },
    { type: "linkedIn", href: "#" },
  ],
};

export function ImmersiveFullScreenNavigation({
  navConfig = NAV_CONFIG,
  navContent = NAV_CONTENT,
}) {
  return (
    <>
      <FullScreenNavigation {...navConfig}>
        {(isOpen) => (
          <ImmersiveFullscreenNavContent
            {...navContent}
            isOpen={isOpen}
            overlayBg={navConfig.overlayBg}
            delay={navConfig.openDuration}
          />
        )}
      </FullScreenNavigation>

      <main className="flex h-screen items-center justify-center bg-white">
        <p className="text-5xl text-neutral-700">Hello !</p>
      </main>
    </>
  );
}

"use client";

import gsap from "gsap";
import Image from "next/image";
import Link from "next/link";
import { useEffect, useRef } from "react";
import { CharStaggerButton } from "../../buttons/char-stagger-button/char-stagger-button";

const LINK_Y_OFFSET = 30;
const IMAGE_INITIAL_SCALE = 0.7;
const IMAGE_ANIMATION_START_SCALE = 0.8;
const SOCIAL_Y_OFFSET = 14;
const HEADER_Y_OFFSET = -12;
const LOCATION_Y_OFFSET = 10;
const DELAY_OFFSET = 0.2;
const TAGLINE_DELAY_OFFSET = 0.08;
const IMAGE_DELAY_OFFSET = 0.1;
const SOCIAL_DELAY_OFFSET = 0.2;
const LOCATION_DELAY_OFFSET = 0.25;

export function ImmersiveFullscreenNavContent({
  links = [],
  images = ["/assets/img/image01.webp", "/assets/img/image02.webp"],
  agencyName = "Hyperiux®",
  socials = [
    { type: "instagram", href: "#" },
    { type: "facebook", href: "#" },
    { type: "twitter", href: "#" },
    { type: "linkedin", href: "#" },
  ],
  location = "Pune, India",
  tagline = "Design. Code. Impact.",
  isOpen = false,
  overlayBg = "#000000",
  delay = 1,
}) {
  const linksRef = useRef([]);
  const imagesRef = useRef([]);
  const socialsRef = useRef([]);
  const agencyRef = useRef(null);
  const taglineRef = useRef(null);
  const locationRef = useRef(null);

  const killAllTweens = () => {
    gsap.killTweensOf([
      ...linksRef.current,
      ...imagesRef.current,
      ...socialsRef.current,
      agencyRef.current,
      taglineRef.current,
      locationRef.current,
    ]);
  };

  const resetAnimatedElements = () => {
    gsap.set(linksRef.current, { y: LINK_Y_OFFSET, opacity: 0 });
    gsap.set(imagesRef.current, { scale: IMAGE_INITIAL_SCALE, opacity: 0 });
    gsap.set(socialsRef.current, { y: SOCIAL_Y_OFFSET, opacity: 0 });
    gsap.set(agencyRef.current, { y: HEADER_Y_OFFSET, opacity: 0 });
    gsap.set(taglineRef.current, { y: HEADER_Y_OFFSET, opacity: 0 });
    gsap.set(locationRef.current, { y: LOCATION_Y_OFFSET, opacity: 0 });
  };

  const setLinkRef = (index) => (element) => {
    linksRef.current[index] = element;
  };

  const setImageRef = (index) => (element) => {
    imagesRef.current[index] = element;
  };

  const setSocialRef = (index) => (element) => {
    socialsRef.current[index] = element;
  };

  useEffect(() => {
    killAllTweens();

    if (!isOpen) {
      return;
    }

    resetAnimatedElements();

    const animationDelay = Math.max(delay - DELAY_OFFSET, 0);

    gsap.fromTo(
      agencyRef.current,
      { y: HEADER_Y_OFFSET, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.6, ease: "power2.out", delay: animationDelay },
    );

    gsap.fromTo(
      taglineRef.current,
      { y: HEADER_Y_OFFSET, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.6,
        ease: "power2.out",
        delay: animationDelay + TAGLINE_DELAY_OFFSET,
      },
    );

    gsap.fromTo(
      linksRef.current,
      { y: LINK_Y_OFFSET, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.8,
        ease: "power2.out",
        stagger: 0.07,
        delay: animationDelay,
      },
    );

    gsap.fromTo(
      imagesRef.current,
      { scale: IMAGE_ANIMATION_START_SCALE, opacity: 0 },
      {
        scale: 1,
        opacity: 1,
        duration: 0.9,
        ease: "power3.out",
        stagger: 0.02,
        delay: animationDelay + IMAGE_DELAY_OFFSET,
      },
    );

    gsap.fromTo(
      socialsRef.current,
      { y: SOCIAL_Y_OFFSET, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.5,
        ease: "power2.out",
        stagger: 0.06,
        delay: animationDelay + SOCIAL_DELAY_OFFSET,
      },
    );

    gsap.fromTo(
      locationRef.current,
      { y: LOCATION_Y_OFFSET, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.5,
        ease: "power2.out",
        delay: animationDelay + LOCATION_DELAY_OFFSET,
      },
    );
  }, [delay, isOpen]);

  return (
    <div
      style={{ backgroundColor: overlayBg }}
      className="flex h-screen w-full flex-col justify-between px-28 py-10 text-white max-sm:px-6 max-sm:py-6"
    >
      <div className="flex items-center justify-between">
        <h2
          ref={agencyRef}
          style={{ opacity: 0, transform: `translateY(${HEADER_Y_OFFSET}px)` }}
          className="text-xl font-medium tracking-wide"
        >
          {agencyName}
        </h2>

        <p
          ref={taglineRef}
          style={{ opacity: 0, transform: `translateY(${HEADER_Y_OFFSET}px)` }}
          className="text-sm opacity-60 max-md:hidden"
        >
          {tagline}
        </p>
      </div>

      <div className="flex items-center justify-between gap-10 max-md:flex-col max-md:items-start max-md:gap-18 max-sm:gap-30">
        <div className="flex flex-col gap-0">
          {links.map((link, index) => (
            <div
              key={link.label}
              ref={setLinkRef(index)}
              style={{ opacity: 0, transform: `translateY(${LINK_Y_OFFSET}px)` }}
            >
              <CharStaggerButton
                href={link.href}
                text={link.label}
                hoverColor="#ff6b00"
                className="z-60 text-[6vw] max-md:text-[7vw] max-sm:text-[11vw]"
              />
            </div>
          ))}
        </div>

        <div className="flex h-full flex-col items-end justify-center gap-40 py-5 max-md:items-start max-md:gap-28 max-sm:w-full max-sm:gap-35 max-sm:py-0">
          <div className="flex items-end gap-8 max-md:gap-10 max-sm:w-full max-sm:gap-3">
            {images.slice(0, 4).map((src, index) => (
              <div
                key={src}
                ref={setImageRef(index)}
                style={{ opacity: 0, transform: `scale(${IMAGE_INITIAL_SCALE})` }}
                className="relative h-[18vw] w-[25vw] overflow-hidden rounded-xl max-md:h-[25vh] max-md:w-[35vw] max-sm:h-[30vw] max-sm:w-[60vw]"
              >
                <Image
                  src={src}
                  alt={`img-${index}`}
                  fill
                  className="object-cover transition duration-500 hover:scale-105"
                />
              </div>
            ))}
          </div>

          <div className="flex gap-16 max-md:gap-16 max-sm:gap-10">
            {socials.map((social, index) => (
              <Link
                key={`${social.type}-${index}`}
                href={social.href}
                ref={setSocialRef(index)}
                style={{ opacity: 0, transform: `translateY(${SOCIAL_Y_OFFSET}px)` }}
              >
                <Image
                  src={social.src ? social.src : `/assets/social-icons/${social.type}.svg`}
                  alt={social.type}
                  width={24}
                  height={24}
                  className="h-7 w-7 opacity-70 transition hover:opacity-100 max-sm:h-5 max-sm:w-5"
                />
              </Link>
            ))}
          </div>
        </div>
      </div>

      <div className="flex items-end justify-end max-sm:justify-between">
        <p className="hidden text-sm opacity-60 max-sm:block">{tagline}</p>
        <p
          ref={locationRef}
          style={{ opacity: 0, transform: `translateY(${LOCATION_Y_OFFSET}px)` }}
          className="text-sm opacity-60"
        >
          {location}
        </p>
      </div>
    </div>
  );
}
